const sensorNum = msg.topic;

// Constants for the Steinhart-Hart equation
const A = 0.001125308852122;
const B = 0.000234711863267;
const C = 0.000000085663516;

const vcc = 3.3;
const resistance_R2 = 10000;

// Function to convert ADC raw value to temperature in degrees Celsius
function adcToTemp(rawValue) {
    // Convert ADC raw value to voltage
    const voltage_R2 = rawValue / 1023 * vcc;

    const voltage_Therm = vcc - voltage_R2;

    const current = voltage_R2 / resistance_R2;

    // Calculate resistance of the thermistor
    const resistance = voltage_Therm / current;

    // Calculate temperature using Steinhart-Hart equation
    const temperature = 1 / (A + B * Math.log(resistance) + C * Math.pow(Math.log(resistance), 3)) - 273.15;

    return temperature;
}

const temperatureCelsius = adcToTemp(msg.payload);
msg.payload = temperatureCelsius;

// Check for overheating
if (temperatureCelsius > 70) {
    const overheatText = ("Overheat! Sensor " + sensorNum + " reading " + temperatureCelsius + " °C!!! Shutting down...");
    const msgOverheat = {payload:overheatText};
    return [msg, msgOverheat];
}

return msg;

const temperature = msg.payload;
const statusMsg = ("Temperature: " + temperature + "°C");
let fillColour = "blue";
if (temperature > 50) fillColour = "red";
else if (temperature > 40) fillColour = "yellow";
node.status({fill:fillColour,shape:"ring",text:statusMsg});
return msg;

