const running = global.get('runState');

if (running) {
    // Get current timestamp, offset for timezone and zero adjust
    const dateTime = new Date();
    const tzOffset = dateTime.getTimezoneOffset() * 60 * 1000;
    const unixtime = dateTime.getTime() + tzOffset;
    const millisInOneDay = 24 * 60 * 60 * 1000;
    const millisToday = unixtime % millisInOneDay;

    // Get current time range from program array
    const progArray = global.get('run_prog_array');
    let ptr = 0;
    for (let i = 19; i >= 0; i--) {
        if (progArray[i][0] < millisToday) {
            ptr = i;
            break;
        }
    }

    let ptr2 = ptr + 1;
    if (ptr2 > 19) ptr2 = 0;
    const tmRangeStart = progArray[ptr][0];
    const tmRangeEnd = progArray[ptr2][0];
    const tmRangePositionFactor = (millisToday - tmRangeStart) / (tmRangeEnd - tmRangeStart);
    const uvRangeStart = progArray[ptr][1];
    const uvRangeEnd = progArray[ptr2][1];
    const uvLevelNow = uvRangeStart + ((uvRangeEnd - uvRangeStart) * tmRangePositionFactor);

    /*msg.payload = { 'ptr':ptr,
                    'tmRangeStart':tmRangeStart/(60*60*1000),
                    'tmRangeEnd':tmRangeEnd/(60*60*1000),
                    'tmRangePositionFactor':tmRangePositionFactor,
                    'uvRangeStart':uvRangeStart,
                    'uvRangeEnd':uvRangeEnd,
                    'uvLevelNow':uvLevelNow};*/

    const uvLevel = global.get('uvLevel');
    const uvLevelNowRounded = uvLevelNow.toFixed(1);
    if (uvLevel != uvLevelNowRounded) {
        msg.payload = uvLevelNowRounded;
        return msg;
    }
}

return;

